import '../../domain/entities/explore_category.dart';
import '../../domain/entities/explore_metadata.dart';
import '../models/explore_content_model.dart';

List<ExploreContentModel> getGlobalLaunchExpansionCatalog(String languageCode) {
  final locale = languageCode.trim().toLowerCase();
  return _items.map((item) => item.toModel(locale)).toList(growable: false);
}

class _LaunchItem {
  const _LaunchItem({required this.id, required this.countryCode, required this.countryName, required this.cityName, required this.category, required this.title, required this.latitude, required this.longitude, required this.coverImageUrl});
  final String id, countryCode, countryName, cityName, title, coverImageUrl;
  final ExploreCategory category;
  final double latitude, longitude;

  ExploreContentModel toModel(String locale) {
    final copy = _copyFor(locale, category.value);
    return ExploreContentModel(
      id: id, countryCode: countryCode, countryName: countryName, cityName: cityName,
      category: category, title: title,
      shortDescription: copy.$1.replaceAll('{city}', cityName).replaceAll('{title}', title),
      description: copy.$2.replaceAll('{city}', cityName).replaceAll('{title}', title),
      latitude: latitude, longitude: longitude, coverImageUrl: coverImageUrl,
      tags: <String>[category.value, cityName.toLowerCase(), countryCode.toLowerCase(), 'global_launch_v3'],
      metadata: ExploreMetadata(
        localTip: copy.$3,
        coordinatePrecision: 'city_area',
        editorialStatus: 'needs_exact_pin_review',
      ),
      galleryImageUrls: const [],
      isFeatured: category == ExploreCategory.place || category == ExploreCategory.food,
    );
  }
}

(String, String, String) _copyFor(String locale, String category) {
  final categoryName = _categoryNames[locale]?[category] ?? _categoryNames['en']![category]!;
  final intro = switch (locale) {
    'tr' => '{title}, {city} için öne çıkan $categoryName keşiflerinden biridir.',
    'de' => '{title} ist eine wichtige $categoryName-Entdeckung in {city}.',
    'fr' => '{title} est une découverte $categoryName à connaître à {city}.',
    'es' => '{title} es una experiencia de $categoryName destacada en {city}.',
    'it' => '{title} è una scoperta di $categoryName da conoscere a {city}.',
    'ar' => '{title} من أبرز اكتشافات $categoryName في {city}.',
    _ => '{title} is a notable $categoryName discovery in {city}.',
  };
  final detail = switch (locale) {
    'tr' => 'Seyahat planına eklemeden önce güncel açılış, erişim, içerik ve yerel koşulları kontrol et. Harita noktası editoryal doğrulama tamamlanana kadar şehir-bölge seviyesindedir.',
    'de' => 'Prüfe vor dem Besuch aktuelle Öffnungszeiten, Zugang und lokale Hinweise. Der Kartenpunkt bleibt bis zur redaktionellen Prüfung auf Stadtebene.',
    'fr' => 'Vérifiez les horaires, l’accès et les informations locales avant la visite. Le point cartographique reste approximatif jusqu’à validation éditoriale.',
    'es' => 'Comprueba horarios, acceso e información local antes de la visita. El punto del mapa es aproximado hasta la revisión editorial.',
    'it' => 'Controlla orari, accesso e indicazioni locali prima della visita. Il punto sulla mappa resta approssimativo fino alla verifica editoriale.',
    'ar' => 'تحقق من أوقات العمل والوصول والإرشادات المحلية قبل الزيارة. تبقى نقطة الخريطة تقريبية حتى اكتمال المراجعة التحريرية.',
    _ => 'Check current opening, access and local guidance before visiting. The map point remains city-area level until editorial pin verification is complete.',
  };
  final tip = switch (locale) {
    'tr' => 'Saat, fiyat ve erişim bilgisini ziyaret öncesi doğrula.',
    'de' => 'Öffnungszeiten, Preise und Zugang vor dem Besuch prüfen.',
    'fr' => 'Vérifiez horaires, prix et accès avant la visite.',
    'es' => 'Verifica horarios, precios y acceso antes de visitar.',
    'it' => 'Verifica orari, prezzi e accesso prima della visita.',
    'ar' => 'تحقق من المواعيد والأسعار وإمكانية الوصول قبل الزيارة.',
    _ => 'Verify hours, pricing and access before visiting.',
  };
  return (intro, detail, tip);
}

